{
  "rules": [
    {
      "id": "check_total_balance",
      "description": "Ensure that the total debits equal the total credits for each journal.",
      "gx_code": "gx.expectations.ExpectMulticolumnSumToEqual(column_list=['total_debits', 'total_credits'], sum_total=0)",
      "evidence_references": ["source_documentation"]
    },
    {
      "id": "check_currency_allowed",
      "description": "Ensure that the currency is either USD or EUR.",
      "gx_code": "gx.expectations.ExpectColumnValuesToBeInSet(column='currency', value_set=['USD', 'EUR'])",
      "evidence_references": ["source_documentation"]
    },
    {
      "id": "check_journal_id_unique",
      "description": "Ensure that the journal_id column contains unique values.",
      "gx_code": "gx.expectations.ExpectColumnValuesToBeUnique(column='journal_id')",
      "evidence_references": ["source_documentation"]
    },
    {
      "id": "check_total_credits_nonnegative",
      "description": "Ensure that the total_credits column contains nonnegative values.",
      "gx_code": "gx.expectations.ExpectColumnValuesToBeBetween(column='total_credits', min_value=0, max_value=1000000000)",
      "evidence_references": ["source_documentation"]
    }
  ],
  "abstentions": []
}
